search:
{% for collection in [posts, pages] %}
{% if collection %}
{% for item in collection.toArray() %}
{% if item.indexing != false %}
  {# Hexo custom permalinks can have a leading slash; config.root already has one. #}
  {% set item_url = (url + (item.path | replace(r/^\/+/, ''))) | uriencode %}

    {{ item.title | escape }}

    {{ item_url | escape }}
    {% if content %}
    {{ item.content | noControlChars | replace('', ']]]]>>') | safe }}
    {% endif %}
    {% if item.categories and item.categories.length > 0 %}

      {% for category in item.categories.toArray() %}{{ category.name | escape }}{% endfor %}

    {% endif %}
    {% if item.tags and item.tags.length > 0 %}

      {% for tag in item.tags.toArray() %}{{ tag.name | escape }}{% endfor %}

    {% endif %}

{% endif %}
{% endfor %}
{% endif %}
{% endfor %}
